#!/usr/bin/env python3
"""A/B：x.ai 是否拒 GIF 图（Claude Code 的 tool_result 里带截图/动图时）。

在 litellm-proxy pod 内跑，经 /v1/messages 打 sa-grok-4.7，关重试关兜底。
  P  tool_result 里一张 PNG（阳性对照，必须 200）
  G  同位置换成一张 GIF            —— 10-14 线上 cursor-limengxin-h4fd 的形状
  T  不带图，纯文本 tool_result      —— 第二个对照
图是本地生成并用 file(1)/Pillow 校验过的 64x64 合法 PNG / GIF89a，内嵌为常量（pod 里没有 Pillow）。
"""
import json, os, sys, urllib.error, urllib.request

B = "http://127.0.0.1:4000"; K = os.environ["LITELLM_MASTER_KEY"]; N = int(os.environ.get("PROBE_N", "2"))

PNG_B64 = "iVBORw0KGgoAAAANSUhEUgAAAEAAAABACAIAAAAlC+aJAAAAeUlEQVR4nO3PQQkAMAzAwCqpfymTNRF7HINABFzm7H7dcEEDWtCAFjSgBQ1oQQNa0IAWNKAFDWhBA1rQgBY0oAUNaEEDWtCAFjSgBQ1oQQNa0IAWNKAFDWhBA1rQgBY0oAUNaEEDWtCAFjSgBQ1oQQNa0IAWNKAFj13Kp0DxHeM4GQAAAABJRU5ErkJggg=="
GIF_B64 = ""

def body(case):
    content = [{"type": "text", "text": "screenshot attached"}]
    if case in ("P", "G"):
        media, data = ("image/png", PNG_B64) if case == "P" else ("image/gif", GIF_B64)
        content.append({"type": "image", "source": {"type": "base64", "media_type": media, "data": data}})
    return {"model": "sa-grok-4.7", "max_tokens": 16, "num_retries": 0, "fallbacks": [], "messages": [
        {"role": "user", "content": "take a screenshot"},
        {"role": "assistant", "content": [{"type": "tool_use", "id": "t1", "name": "screenshot", "input": {}}]},
        {"role": "user", "content": [{"type": "tool_result", "tool_use_id": "t1", "content": content},
                                     {"type": "text", "text": "Reply with the single word: ok"}]}]}

def call(b):
    r = urllib.request.Request(B + "/v1/messages", data=json.dumps(b).encode(), method="POST",
                               headers={"x-api-key": K, "Authorization": "Bearer " + K, "Content-Type": "application/json", "anthropic-version": "2023-06-01"})
    try:
        with urllib.request.urlopen(r, timeout=90) as resp: return resp.status, ""
    except urllib.error.HTTPError as e: return e.code, e.read().decode("utf-8", "replace")[:200]
    except Exception as e: return -1, f"{type(e).__name__}: {e}"[:200]

summary = {}
for case in sys.argv[1:] or ["P", "G", "T"]:
    codes = []
    for i in range(N):
        c, err = call(body(case)); codes.append(c)
        print(f"case={case} try={i+1} status={c}" + (f" err={err!r}" if err else ""), flush=True)
    summary[case] = codes
print("SUMMARY " + json.dumps(summary))
sys.exit(2 if any(c != 200 for c in summary.get("P", [200])) else 0)
